class Solution {
public:
    int minimumRecolors(std::string blocks, int k) {
        int cur_w = 0;
        for (int i = 0; i < k; ++i) {
            if (blocks[i] == 'W') cur_w++;
        }
        int ans = cur_w;
        for (size_t i = k; i < blocks.size(); ++i) {
            if (blocks[i] == 'W') cur_w++;
            if (blocks[i - k] == 'W') cur_w--;
            ans = std::min(ans, cur_w);
        }
        return ans;
    }
};

class Solution {
    public int minimumRecolors(String blocks, int k) {
        int curW = 0;
        for (int i = 0; i < k; ++i) {
            if (blocks.charAt(i) == 'W') curW++;
        }
        int ans = curW;
        for (int i = k; i < blocks.length(); ++i) {
            if (blocks.charAt(i) == 'W') curW++;
            if (blocks.charAt(i - k) == 'W') curW--;
            ans = Math.min(ans, curW);
        }
        return ans;
    }
}

var minimumRecolors = function(blocks, k) {
    let curW = 0;
    for (let i = 0; i < k; ++i) {
        if (blocks[i] === 'W') curW++;
    }
    let ans = curW;
    for (let i = k; i < blocks.length; ++i) {
        if (blocks[i] === 'W') curW++;
        if (blocks[i - k] === 'W') curW--;
        if (curW < ans) ans = curW;
    }
    return ans;
};
